151	func (s *Store) DeleteAttachments(ctx context.Context, attachments []*Attachment) error {
152		if len(attachments) == 0 {
153			return nil
154		}
155	
156		deletes := make([]*DeleteAttachment, 0, len(attachments))
157		for _, attachment := range attachments {
158			if attachment == nil {
159				continue
160			}
161			deletes = append(deletes, &DeleteAttachment{ID: attachment.ID, MemoID: attachment.MemoID})
162		}
163		if len(deletes) == 0 {
164			return nil
165		}
166	
167		if err := s.driver.DeleteAttachments(ctx, deletes); err != nil {
168			return err
169		}
170	
171		instanceStorageSetting, instanceStorageSettingErr := s.getAttachmentStorageCleanupInstanceSetting(ctx, attachments)
172		for _, attachment := range attachments {
173			if attachment == nil {
174				continue
175			}
176			var err error
177			if instanceStorageSettingErr != nil && AttachmentNeedsInstanceStorageSetting(attachment) {
178				err = instanceStorageSettingErr
179			} else {
180				err = s.deleteAttachmentStorageImpl(ctx, attachment, instanceStorageSetting)
181			}
182			if err != nil {
183				if attachment.StorageType == storepb.AttachmentStorageType_LOCAL {
184					return errors.Wrap(err, "failed to delete local file")
185				}
186				slog.Warn("Failed to delete attachment storage", slog.Any("err", err))
187			}
188		}
